from fastapi import FastAPI, BackgroundTasks
import time

app = FastAPI()

def send_welcome_email(email: str):
  time.sleep(2) # Runs in background after response

# ✅ NEW: Response is sent instantly (0ms latency); email sends in background
@app.post('/register')
def register_user(email: str, background_tasks: BackgroundTasks):
  save_to_db(email)
  background_tasks.add_task(send_welcome_email, email) # ✅ Scheduled post-response
  return {'message': 'User registered'}
